arguments.command:
source /opt/miniconda3/bin/activate testbed && python3 -c "
import py7zr
passwords = ['saint', 'Saint', 'SAINT', 'seven', 'Seven', 'SEVEN', '7z', '7Z', 'st', 'St', 'vault', 'Vault', 'pty', 'PTY', 'terminal', 'Terminal']
for pwd in passwords:
    try:
        with py7zr.SevenZipFile('/tmp/pty_backup.7z', mode='r', password=pwd) as archive:
            archive.extractall('/tmp/pty_restore')
            print(f'Success with password: {pwd}')
            for f in archive.getnames():
                print(f'  {f}')
            break
    except Exception as e:
        pass
else:
    print('No password worked from the list')
"

